use regex_automata::{meta::Regex, Input};

fn main() {
    let pat = r"(?:(?m:^)|\W)(([\w]+[.])*domain[.](\w)+)(?:\W|(?m:$))";
    let re = Regex::new(pat).unwrap();
    for hay in [
        "some.domain.com/x/y",
        "abc.domain.com/x",
        "some.domain.com/x",
        "some.domain.com/",
    ] {
        let input = Input::new(hay.as_bytes());
        let mut caps = re.create_captures();
        re.search_captures(&input, &mut caps);
        println!(
            "{hay:?}: overall={:?} g1={:?}",
            caps.get_group(0).map(|s| (s.start, s.end)),
            caps.get_group(1).map(|s| (s.start, s.end)),
        );
    }
}

