use grep_matcher::{Captures, Matcher};
use grep_regex::RegexMatcherBuilder;

fn main() {
    let patterns = [
        "foo",
        "o",
        "fo+",
        "([\\w]+[.])*domain[.](\\w)+",
        "-2",
        "a|b",
        "foo|x",
        "!?foo!?",
        "foo!?",
        "!?foo",
        ".",
        "\\w+",
    ];
    let hays = [
        "some.domain.com/x/y\nabc.domain.com/x\nsome.domain.com/x\nsome.domain.com/\n",
        "xxx\nfoo\nxxx\nfoo\n",
        "xxfoo\nfoo\nxxfoo\n",
        "abc -2 foo\n-2\nfoo-2\n",
        "!foo!\n!!foo!!\na!foo!a\n",
        "foo\r\nbar\r\nfoo\r\n",
        "some.domain.com/x/y\r\nabc.domain.com/x\r\n",
    ];
    let mut bad = 0;
    for &crlf in &[false, true] {
        for pat in patterns {
            let mut b = RegexMatcherBuilder::new();
            b.word(true).multi_line(true).line_terminator(Some(b'\n'));
            if crlf {
                b.crlf(true);
            }
            let m = b.build(pat).unwrap();
            for hay in hays {
                for at in 0..=hay.len() {
                    let f = m.find_at(hay.as_bytes(), at).unwrap();
                    let mut caps = m.new_captures().unwrap();
                    let ok = m.captures_at(hay.as_bytes(), at, &mut caps).unwrap();
                    let c = if ok {
                        caps.get(0).map(|m| (m.start(), m.end()))
                    } else {
                        None
                    };
                    let f = f.map(|m| (m.start(), m.end()));
                    if f != c {
                        bad += 1;
                        println!(
                            "MISMATCH crlf={crlf} pat={pat:?} at={at} hay={hay:?}\n  find={f:?} caps={c:?}"
                        );
                    }
                }
            }
        }
    }
    println!("bad={bad}");
}

